-- PRIVATE SOURCE ONLY: committed3995, known152-to154 journal authorization.
-- Four existing runtime facades plus private source_value, NOT source facade.
-- No capacity, writer, IAM assignment, contract, identity, grant or data change.
DO $journal_preparation_authorization_207$
DECLARE expected jsonb;actual pg_proc;runtime_oid oid;original_functions jsonb:='[]';prior jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'repeatable read' OR current_setting('server_version_num')::integer/10000 NOT IN(17,18) THEN RAISE EXCEPTION 'JOURNAL_AUTHORIZATION_CONTEXT_REQUIRED';END IF;
 PERFORM pg_advisory_xact_lock(152);PERFORM pg_advisory_xact_lock(176);PERFORM pg_advisory_xact_lock(207);
 runtime_oid:=to_regrole('municontrol_actions_runtime_app');IF runtime_oid IS NULL OR runtime_oid=current_user::regrole THEN RAISE EXCEPTION 'JOURNAL_AUTHORIZATION_PREREQUISITE';END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements('[{"name":"own_journal_immutable_v1","signature":"public.own_journal_immutable_v1()","argNames":null,"result":"trigger","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"v","bodySha256":"38bdef280b38254508c024a28e6b211e389683cf1b61031d95b2d820888c96c2","definitionSha256":"13159c95ed834f218d1219226089fb8e5a6bbbbaee61d4b77a8d65385d05d814"},{"name":"own_journal_lock_v1","signature":"public.own_journal_lock_v1(jsonb)","argNames":["ctx"],"result":"void","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"v","bodySha256":"8eda85e968f96d8c2b5aa592cc0def847787777045116a17cae3f9935da2d940","definitionSha256":"7c5da2ead11e34143c40239fe0cb48240da8548a196cfd8d461a664372626d9b"},{"name":"own_journal_text_v1","signature":"public.own_journal_text_v1(jsonb,integer,integer)","argNames":["v","min_length","max_length"],"result":"boolean","language":"sql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"i","bodySha256":"13e57a2c42a78db1ff3cbd85774218e92d7b537d01d6c1f089dbfb967c61715d","definitionSha256":"8483a64d1e2ac2d8b0ce92bfd064984b279a6142ca4809a416ec9b4dc7738b3d"},{"name":"own_journal_command_body_v1","signature":"public.own_journal_command_body_v1(jsonb)","argNames":["v"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"i","bodySha256":"5dc1c62dc673547d545297127174f4546f03e0623b62bd23d2002d027385a586","definitionSha256":"96deaaf459ca12fa8eb4e670cdf6b681213ec39b4d4932a5e0645529e83ac45c"},{"name":"own_journal_calculate_v1","signature":"public.own_journal_calculate_v1(jsonb,text,jsonb)","argNames":["s","day_value","rules_value"],"result":"jsonb","language":"plpgsql","defaul