56":"8a4c153be142317ec3b1b3ea39f54061d3d1c76ce1ae058cf83ee83ace24e14b","definitionSha256":"4e925c9f7349eaceceff880405b80b10736c711f6c3249605c3ffdfd4b7b7b80"},{"name":"own_journal_bootstrap_v1","signature":"public.own_journal_bootstrap_v1(jsonb,text,text)","argNames":["p","period_value","type_value"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"volatility":"v","bodySha256":"2d7e446f3a90876e1120e8d4484f03b464b99dac37f96b79f67aa42b9fc85ee6","definitionSha256":"12e18e6c5a928e72de9a21a92a0a8033ced0bd0b6ca11ee9865e62f2935a494c"},{"name":"own_journal_duplicate_v1","signature":"public.own_journal_duplicate_v1(jsonb,jsonb,uuid)","argNames":["ctx","s","ignored_proposal"],"result":"boolean","language":"sql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":false,"volatility":"s","bodySha256":"e20c91d1c61d5a2ef4ba53e8fb4f708acdb17209476c516be3054e0291c262c1","definitionSha256":"b10fe70c48446eb982656e27e644653cb7520892b764b56720784b63cce3ac9a"},{"name":"own_journal_attempt_v1","signature":"public.own_journal_attempt_v1(jsonb,uuid)","argNames":["p","key"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp"],"runtime":true,"volatility":"v","bodySha256":"f258c16631eada6988cb8e72a2074ecd132fe1beb7e68b59586fb3b7ebfecd81","definitionSha256":"47ddb5b4929d1418e7301ef58c799ed178e8cbc0cab04c46be99bb49f44ec38a"},{"name":"own_journal_command_v1","signature":"public.own_journal_command_v1(jsonb,jsonb,uuid)","argNames":["p","body_value","key"],"result":"jsonb","language":"plpgsql","defaults":0,"defaultExpressions":"","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true,"volatility":"v","bodySha256":"eb1992576343f4d2daae62c3a453f53b0723616eb436064c281f6b41429c1c55","definitionSha256":"c6671e53f4b80ca76fffc65fcc5589e17ef273f7f4f94